const final = {};
let mensagens = [];

for (const item of items) {
  const json = item.json;

  // Junta mensagens
  if (json.Messagem) {
    mensagens.push(json.Messagem);
  }

  // Copia os demais campos (sem sobrescrever mensagens)
  for (const key in json) {
    if (key !== 'Messagem') {
      final[key] = json[key];
    }
  }

  // Extrai o telefone e trata o 9º dígito
  if (json.From && !final.telefone) {
    const raw = json.From.split('@')[0]; // Ex: 557193643490
    const ddi = raw.slice(0, 2);         // 55
    const ddd = raw.slice(2, 4);         // 71
    let restante = raw.slice(4);         // 93643490 ou 993643490

    // Se começar com '99', fatia a string e remove o primeiro caractere
    if (restante.startsWith('99')) {
      restante = restante.substring(1);
    } 
    // Se o número vier completamente sem o 9 inicial, nós o adicionamos
    else if (!restante.startsWith('9')) {
      restante = '9' + restante;
    }

    final.telefone = `${ddi}${ddd}${restante}`;
  }
}

final.Messagem = mensagens.join('\n');

// Captura, converte e injeta o timestamp formatado
const rawTimestamp = $input.first().json.timestamp;
if (rawTimestamp) {
  // Converte para Number, multiplica por 1000 e aplica o fuso horário correto
  final.data_ultimo_contato = new Date(Number(rawTimestamp) * 1000).toLocaleString('pt-BR', { 
    timeZone: 'America/Bahia' 
  });
}

return [
  {
    json: final
  }
];

// Puxa o output do nó usando a sintaxe moderna e previne erros de 'undefined'
const texto = $('Orquestrador de IA').first().json.output || "";

const mensagens = texto
  .split(/\n+/)  // Quebra a string onde houver uma ou mais quebras de linha reais
  .map(p => p.trim()) // Limpa a sujeira de espaços invisíveis nas pontas
  .filter(p => p.length > 0); // Joga no lixo qualquer linha que ficou vazia

// Devolve o array perfeitamente fatiado para o n8n iterar
return mensagens.map(mensagem => ({
  json: { text: mensagem }
}));

return [
  {
    json: {},
    binary: {
      data: {
        data: Buffer.from($json.data.base64, 'base64'),
        mimeType: $json.data.mimetype,
        fileName: $json.data.fileName,
      }
    }
  }
]
